
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_tw2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_tw2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.451013995318705e+01, 9.084858295110986e+01, 8.584128567438049e+01, 7.914287343713592e+01, 7.046014948308779e+01, 5.969928729457570e+01, 4.718385728150943e+01, 3.386766305972174e+01, 2.133484385375538e+01, 1.132829836761121e+01, 4.988967137180834e+00, 2.540276064327764e+00, 1.914790142829567e+00, 1.274366264253234e+00, 6.434081497728396e-01, 2.381830418514352e-01, 5.779162586505047e-02, 6.958272781151182e-03, 3.208952824116086e-04, 4.025177647916449e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


